SELECT     t.id AS "ID do Projeto",     t.name AS "Nome do Projeto",     c.id AS "Id do Curso",     c.fullname AS "Nome do Curso",     cat.name AS "Categoria do Curso",     u.id AS "Id do Usuário",     CONCAT(u.firstname, ' ', u.lastname) AS "Nome do usuário",     COALESCE(NULLIF(CAST(u.username AS CHAR), ''), 'CPF não informado') AS "CPF do Usuário",     COALESCE(CAST(cfd.value AS DECIMAL), 0) AS "Carga Horária",          CASE         WHEN cc.timecompleted IS NOT NULL THEN 'Concluído'         ELSE 'Em andamento'     END AS "Status do Progresso",      DATE_FORMAT(FROM_UNIXTIME(ue.timecreated), '%d/%m/%Y %H:%i') AS "Data de Inscrição",     DATE_FORMAT(FROM_UNIXTIME(ula.timeaccess), '%d/%m/%Y %H:%i') AS "Último Acesso ao Curso",     FROM_UNIXTIME(ue.timecreated) AS "Data de Matrícula (Data)",     scorm_log.first_access AS "Primeiro Acesso SCORM",     FROM_UNIXTIME(ula.timeaccess) AS "Último Acesso ao Curso (Data)",     FROM_UNIXTIME(cc.timecompleted) AS "Data de Conclusão",      CASE         WHEN cc.timecompleted IS NOT NULL THEN 'Concluinte'         WHEN scorm_log.first_access IS NOT NULL              AND cc.timecompleted IS NULL              AND (ula.timeaccess IS NOT NULL                   AND FROM_UNIXTIME(ula.timeaccess) > DATE_SUB(NOW(), INTERVAL 20 DAY))              THEN 'Evadido'         WHEN scorm_log.first_access IS NOT NULL              AND cc.timecompleted IS NULL              AND (ula.timeaccess IS NOT NULL                   AND FROM_UNIXTIME(ula.timeaccess) >= DATE_SUB(NOW(), INTERVAL 20 DAY))              THEN 'Em Andamento'         WHEN scorm_log.first_access IS NOT NULL              AND (FROM_UNIXTIME(scorm_log.first_access) <= DATE_ADD(FROM_UNIXTIME(ue.timecreated), INTERVAL 20 DAY))              THEN 'Iniciado'         WHEN scorm_log.first_access IS NULL              AND (FROM_UNIXTIME(ue.timecreated) >= DATE_SUB(NOW(), INTERVAL 20 DAY))              THEN 'Em Processo'         WHEN NOW() > DATE_ADD(FROM_UNIXTIME(ue.timecreated), INTERVAL 20 DAY)              AND (                  course_log.first_access IS NULL                  OR FROM_UNIXTIME(course_log.first_access) > DATE_ADD(FROM_UNIXTIME(ue.timecreated), INTERVAL 20 DAY)              )              THEN 'Desistente'         ELSE 'Não iniciados'     END AS "Status do Usuário por Curso"  FROM mdl_tool_tenant AS t JOIN mdl_tool_tenant_user AS tu     ON t.id = tu.tenantid JOIN mdl_user AS u     ON u.id = tu.userid JOIN mdl_user_enrolments AS ue     ON ue.userid = u.id JOIN mdl_enrol AS e     ON ue.enrolid = e.id JOIN mdl_course AS c     ON c.id = e.courseid LEFT JOIN mdl_course_completions AS cc     ON cc.userid = u.id AND cc.course = c.id LEFT JOIN mdl_customfield_data AS cfd     ON cfd.instanceid = c.id AND cfd.fieldid = 5 LEFT JOIN mdl_course_categories AS cat     ON cat.id = c.category LEFT JOIN mdl_user_lastaccess AS ula     ON ula.userid = u.id AND ula.courseid = c.id  LEFT JOIN (     SELECT         l.userid,         l.courseid,         MIN(l.timecreated) AS first_access     FROM mdl_logstore_standard_log AS l     WHERE l.courseid IS NOT NULL     GROUP BY l.userid, l.courseid ) AS course_log     ON course_log.userid = u.id AND course_log.courseid = c.id  LEFT JOIN (     SELECT         l.userid,         l.courseid,         DATE_FORMAT(FROM_UNIXTIME(MIN(l.timecreated)), '%d/%m/%Y %H:%i:%s') AS first_access     FROM mdl_logstore_standard_log AS l     WHERE l.eventname = '\\mod_scorm\\event\\sco_launched'     GROUP BY l.userid, l.courseid ) AS scorm_log     ON scorm_log.userid = u.id AND scorm_log.courseid = c.id  WHERE     u.deleted = 0     AND u.suspended = 0     AND NOT EXISTS (         SELECT 1         FROM mdl_user_info_data AS ud         JOIN mdl_user_info_field AS uf             ON uf.id = ud.fieldid         WHERE             ud.userid = u.id             AND uf.shortname = 'obs'             AND ud.data = '0'     )  GROUP BY     t.id,     t.name,     c.id,     c.fullname,     cat.name,     u.id,     u.firstname,     u.lastname,     u.username,     cc.timecompleted,     ue.status,     ue.timecreated,     ula.timeaccess,     cfd.value,     scorm_log.first_access,     course_log.first_access  ORDER BY     "Nome do Projeto",     "Nome do Curso",     "Nome do usuário";
